"""
Client for the qBraid Agents service.

"""

from typing import NoReturn, Optional

from qbraid_core.client import QbraidClientV1
from qbraid_core.exceptions import RequestsApiError
from qbraid_core.registry import register_client
from qbraid_core.sessions import QbraidSessionV1

from .exceptions import AgentServiceRequestError, AgentSessionNotFoundError
from .schemas import AgentSession, AgentSessionSummary


@register_client()
class AgentsClient(QbraidClientV1):
    """Client for interacting with the qBraid Agents service.

    Provides cloud sync for agent sessions and stubs for future
    messaging and team orchestration APIs.

    Args:
        api_key: Optional API key for authentication.
        session: Optional pre-configured session.

    Example:
        >>> from qbraid_core.services.agents import AgentsClient
        >>> client = AgentsClient()
        >>> sessions = client.list_sessions()
    """

    def __init__(
        self,
        api_key: Optional[str] = None,
        session: Optional[QbraidSessionV1] = None,
    ):
        """Initialize the AgentsClient."""
        super().__init__(api_key=api_key, session=session)

    def _handle_error(self, err: RequestsApiError, operation: str) -> NoReturn:
        """Handle API errors and raise appropriate exceptions."""
        err_str = str(err).lower()

        if "404" in err_str or "not found" in err_str:
            raise AgentSessionNotFoundError(f"Session not found: {err}") from err

        raise AgentServiceRequestError(f"Failed to {operation}: {err}") from err

    # =========================================================================
    # Session sync
    # =========================================================================

    def sync_sessions(self, sessions: list[AgentSession]) -> dict:
        """Push local sessions to the cloud.

        Args:
            sessions: List of local AgentSession objects to sync.

        Returns:
            Dict with sync status.
        """
        try:
            payload = [s.model_dump(mode="json", by_alias=True) for s in sessions]
            response = self.session.post("/agents/sessions/sync", json={"sessions": payload})
            resp_json = response.json()
            return resp_json.get("data", resp_json)
        except RequestsApiError as err:
            self._handle_error(err, "sync sessions")

    def list_sessions(
        self,
        tool: Optional[str] = None,
        machine_id: Optional[str] = None,
    ) -> list[AgentSessionSummary]:
        """List agent sessions from the cloud.

        Args:
            tool: Filter by tool ("claude", "codeq", "codex").
            machine_id: Filter by machine ID.

        Returns:
            List of AgentSessionSummary objects.
        """
        params = {}
        if tool is not None:
            params["tool"] = tool
        if machine_id is not None:
            params["machineId"] = machine_id

        try:
            response = self.session.get("/agents/sessions", params=params if params else None)
            resp_json = response.json()
            sessions_data = resp_json.get("data", [])
            return [AgentSessionSummary.model_validate(s) for s in sessions_data]
        except RequestsApiError as err:
            self._handle_error(err, "list sessions")

    def get_session(self, session_id: str) -> AgentSession:
        """Get a specific session from the cloud.

        Args:
            session_id: The session ID.

        Returns:
            AgentSession with full details.

        Raises:
            AgentSessionNotFoundError: If session doesn't exist.
        """
        try:
            response = self.session.get(f"/agents/sessions/{session_id}")
            resp_json = response.json()
            return AgentSession.model_validate(resp_json.get("data", resp_json))
        except RequestsApiError as err:
            self._handle_error(err, f"get session '{session_id}'")

    def delete_session(self, session_id: str) -> dict:
        """Delete a session from the cloud.

        Args:
            session_id: The session ID.

        Returns:
            Dict with deletion status.
        """
        try:
            response = self.session.delete(f"/agents/sessions/{session_id}")
            resp_json = response.json()
            return resp_json.get("data", resp_json)
        except RequestsApiError as err:
            self._handle_error(err, f"delete session '{session_id}'")
